from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    used = [False] * len(tiles)
    rows = [0] * h
    full = (1 << w) - 1

    def solve(remaining):
        # find first empty cell
        r = -1
        c = -1
        for i in range(h):
            if rows[i] != full:
                r = i
                m = rows[i]
                c = 0
                while (m >> c) & 1:
                    c += 1
                break
        if r == -1:
            return True
        for i, (a, b) in enumerate(tiles):
            if used[i]:
                continue
            if a * b > remaining:
                continue
            orients = [(a, b)] if a == b else [(a, b), (b, a)]
            for th, tw in orients:
                if r + th > h or c + tw > w:
                    continue
                mask = ((1 << tw) - 1) << c
                ok = True
                for k in range(r, r + th):
                    if rows[k] & mask:
                        ok = False
                        break
                if not ok:
                    continue
                for k in range(r, r + th):
                    rows[k] |= mask
                used[i] = True
                if solve(remaining - a * b):
                    return True
                used[i] = False
                for k in range(r, r + th):
                    rows[k] &= ~mask
        return False

    return solve(h * w)
