    feats = {}
    for b in range(-7, 8):
        for c in range(-7, 8):
            o12 = max(0, 7 - abs(b))
            o13 = max(0, 7 - abs(c))
            o23 = max(0, 7 - abs(b - c))
            o123 = max(0, min(7, b + 7, c + 7) - max(0, b, c))
            key = (o12, o13, o23, o123)
            if key not in feats:
                feats[key] = (b, c)

    items = list(feats.items())
    for kx, (bx, cx) in items:
        for ky, (by, cy) in items:
            for kz, (bz, cz) in items:
                t = kx[3] * ky[3] * kz[3]
                if t != V3:
