                p = (kx[0] * ky[0] * kz[0]
                     + kx[1] * ky[1] * kz[1]
                     + kx[2] * ky[2] * kz[2])
                if p - 3 * t != V2:
                    continue
                # V1 is determined by the volume identity checked above
                return (0, 0, 0, bx, by, bz, cx, cy, cz)
    return None
