from math import isqrt

def find_largest_400_number(a: int) -> int:
    """ Find the largest 400 number not exceeding a."""
    # primes up to 1000 (enough for m <= 10^6)
    limit = 1000
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    primes = [i for i in range(2, limit + 1) if sieve[i]]

    def distinct_count(m: int) -> int:
        cnt = 0
        for p in primes:
            if p * p > m:
                break
            if m % p == 0:
                cnt += 1
                while m % p == 0:
                    m //= p
                if cnt > 2:
                    return cnt
        if m > 1:
            cnt += 1
        return cnt

    m = isqrt(a)
    while m >= 6:
        if distinct_count(m) == 2:
            return m * m
        m -= 1
    return 36
```

