```
def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    # D[m]: dict (digit_sum, digit_product) -> count of strings of m digits from 1..9
    D = [{(0, 1): 1}]
    for _ in range(9):
        prev = D[-1]
        cur = {}
        for (sm, p), c in prev.items():
            for x in range(1, 10):
                key = (sm + x, p * x)
                cur[key] = cur.get(key, 0) + c
        D.append(cur)

    def f(N):
        # number of beautiful integers in [1, N]
        if N <= 0:
            return 0
        s = str(N)
        L = len(s)
        total = 0  # numbers <= N with no zero digit
        beau = 0   # of those, beautiful
        for k in range(1, L):
            for (sm, p), c in D[k].items():
                total += c
                if p % sm == 0:
                    beau += c
        ps, pp = 0, 1
        completed = True
        for i, ch in enumerate(s):
            d = int(ch)
            m = L - i - 1
            for x in range(1, d):
                bs = ps + x
                bp = pp * x
                for (sm, p), c in D[m].items():
                    total += c
                    if (bp * p) % (bs + sm) == 0:
                        beau += c
            if d == 0:
                completed = False
                break
            ps += d
            pp *= d
        if completed:
            total += 1
            if pp % ps == 0:
                beau += 1
        # numbers containing a zero digit are always beautiful (product 0)
        return (N - total) + beau

    return f(r) - f(l - 1)
```

