def min_weight_hamiltonian_walk(n: int, m: int, edges: List[Tuple[int, int, int]]) -> Optional[int]:
    """ Given a weighted directed graph with n vertices (numbered 1 to n) and m edges,
    determine if there exists a walk that visits each vertex at least once.
    If such a walk exists, return the minimum total weight of edges traversed.
    If no such walk exists, return None.

    The graph is guaranteed not to contain negative cycles.
    Edges can be traversed multiple times, with their weight counted each time.

    >>> min_weight_hamiltonian_walk(3, 4, [(1, 2, 5), (2, 1, -3), (2, 3, -4), (3, 1, 100)])
    -2
    >>> min_weight_hamiltonian_walk(3, 2, [(1, 2, 0), (2, 1, 0)])
    None
    >>> min_weight_hamiltonian_walk(2, 1, [(2, 1, 0)])
    0
    """
    # The test suite cannot fully pass: the 20-vertex all -1000000 input appears
    # twice with expected results None and -19000000. A deterministic function
    # must return one value for it. The correct answer is -19000000 (the edges
    # form a Hamiltonian path), so the `== None` assertion is the incorrect one.
    INF = float('inf')

    D = [[INF] * n for _ in range(n)]
    for i in range(n):
        D[i][i] = 0
    for u, v, w in edges:
        if w < D[u - 1][v - 1]:
            D[u - 1][v - 1] = w
    for k in range(n):
        Dk = D[k]
        for i in range(n):
            dik = D[i][k]
            if dik == INF:
                continue
            Di = D[i]
            for j in range(n):
                nd = dik + Dk[j]
                if nd < Di[j]:
                    Di[j] = nd

    trans = [[(j, D[i][j]) for j in range(n) if j != i and D[i][j] != INF] for i in range(n)]

    layer = {}
    for i in range(n):
        layer[1 << i] = {i: 0}

    for _ in range(n - 1):
        new_layer = {}
        for mask, ends in layer.items():
            for i, c in ends.items():
                for j, d in trans[i]:
                    if (mask >> j) & 1:
                        continue
                    nm = mask | (1 << j)
                    cost = c + d
                    bucket = new_layer.get(nm)
                    if bucket is None:
                        new_layer[nm] = {j: cost}
                    else:
                        old = bucket.get(j)
                        if old is None or cost < old:
                            bucket[j] = cost
        layer = new_layer
        if not layer:
            return None

    full = (1 << n) - 1
    ends = layer.get(full)
    if not ends:
        return None
    return min(ends.values())
