    for i in range(n):
        d[i][i] = 0
    for u, v, w in edges:
        if w < d[u - 1][v - 1]:
            d[u - 1][v - 1] = w
    # Floyd-Warshall (no negative cycles)
    for k in range(n):
        dk = d[k]
        for i in range(n):
            dik = d[i][k]
            if dik == INF:
                continue
            di = d[i]
            for j in range(n):
                nd = dik + dk[j]
                if nd < di[j]:
                    di[j] = nd

    adj = [[(u, d[v][u]) for u in range(n) if u != v and d[v][u] != INF]
           for v in range(n)]

    # layered sparse DP: state (mask, last) -> min cost
    layer = {}
    for v in range(n):
        layer[(1 << v, v)] = 0
    for _ in range(n - 1):
        nxt = {}
        for (mask, v), c in layer.items():
            for u, w in adj[v]:
                bit = 1 << u
                if mask & bit:
                    continue
                key = (mask | bit, u)
                nc = c + w
                old = nxt.get(key)
                if old is None or nc < old:
                    nxt[key] = nc
        layer = nxt
        if not layer:
            return None

    if not layer:
        return None
    return int(min(layer.values()))
