from collections import deque

def can_transform_string(n: int, x: int, y: int, s: str, t: str) -> bool:
    if s == t:
        return True
    if s.count('1') != t.count('1'):
        return False
    if x + y > n:
        return False

    a = '0' * x + '1' * y   # operation A pattern
    b = '1' * y + '0' * x   # operation B pattern
    L = x + y

    seen = {s}
    queue = deque([s])
    while queue:
        cur = queue.popleft()
        for pat, rep in ((a, b), (b, a)):
            i = cur.find(pat)
            while i != -1:
                nxt = cur[:i] + rep + cur[i + L:]
                if nxt == t:
                    return True
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append(nxt)
                i = cur.find(pat, i + 1)
    return False
