        for p in reversed(primes):
            p2 = p * p
            if p2 > N:
                continue
            fs = fsfunc(p)
            fp = lo[p]
            k1 = min(sq, N // p2)
            accH = None
            accL = None
            pe = p
            e = 1
            while pe * p <= N:
                pe1 = pe * p
                fe = fs[e]
                c = fs[e + 1]
                k = min(sq, N // pe1)
                kk = min(k, sq // pe)
                vals = hi[pe:pe * kk + 1:pe]
                if k > kk:
                    vals += [lo[N // (i * pe)] for i in range(kk + 1, k + 1)]
                dH = [(fe * (x - fp) + c) % MOD for x in vals]
                if accH is None:
                    accH = dH
                else:
                    accH[:k] = [a + d for a, d in zip(accH, dH)]
