                    dL = [(fe * (lo[v // pe] - fp) + c) % MOD
                          for v in range(pe1, sq + 1)]
                    if accL is None:
                        accL = [0] * (sq + 1 - p2)
                    off = pe1 - p2
                    accL[off:] = [a + d for a, d in zip(accL[off:], dL)]
                pe = pe1
                e += 1
            hi[1:k1 + 1] = [(h + a) % MOD for h, a in zip(hi[1:k1 + 1], accH)]
            if accL is not None:
                lo[p2:] = [(h + a) % MOD for h, a in zip(lo[p2:], accL)]
        return hi[1]

    GA = phase2(Alo, Ahi, fsA)
    GB = phase2(Blo, Bhi, fsB)
    return (GA - GB) % MOD


def count_good_sequences(N: int, M: int) -> int:
    key = (N, M)
    if key in _cache:
